from pathlib import Path

css_path = Path('predictions-premium-v4.css')
html_path = Path('predictions.html')
marker = '/* JOLS Predictions v4 correction pass — tier semantics and responsive layout */'
patch = r'''

/* JOLS Predictions v4 correction pass — tier semantics and responsive layout */

/* Use the actual tier containers generated by predictions.js. */
body .prediction-balls.prediction-tier-grid {
    display: grid !important;
    grid-template-columns: minmax(0, .82fr) minmax(0, 1.18fr) !important;
    align-items: stretch !important;
    gap: 12px !important;
    width: min(650px, 100%) !important;
    margin: 20px auto 18px !important;
}

body .prediction-tier-grid .prediction-tier {
    display: grid !important;
    align-content: center !important;
    justify-items: center !important;
    gap: 12px !important;
    min-width: 0 !important;
    min-height: 138px !important;
    margin: 0 !important;
    padding: 15px 13px 19px !important;
    border-radius: 17px !important;
    background: rgba(255,255,255,.92) !important;
    box-shadow: inset 0 1px 0 rgba(255,255,255,.94), 0 8px 20px rgba(15,23,42,.045) !important;
}

body .prediction-tier-grid .prediction-tier-sure {
    border: 1px solid rgba(34,197,94,.28) !important;
    background: linear-gradient(145deg,#f1fff6,#ffffff) !important;
}

body .prediction-tier-grid .prediction-tier-direct {
    border: 1px solid rgba(212,154,23,.30) !important;
    background: linear-gradient(145deg,#fffaf0,#ffffff) !important;
}

body .prediction-tier-title {
    color: #10243a !important;
    font-size: 11px !important;
    font-weight: 950 !important;
    letter-spacing: .06em !important;
    line-height: 1.25 !important;
    text-align: center !important;
    text-transform: uppercase !important;
}

body .prediction-tier-balls {
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    flex-wrap: nowrap !important;
    gap: 10px !important;
}

/* Remove the generic nth-child labels from v1; tier classes are authoritative. */
body .prediction-tier-grid .number-ball::after {
    display: block !important;
    left: 50% !important;
    bottom: -18px !important;
    transform: translateX(-50%) !important;
    padding: 3px 6px !important;
    border-radius: 999px !important;
    font-size: 6px !important;
    font-weight: 950 !important;
    letter-spacing: .06em !important;
    white-space: nowrap !important;
}

body .prediction-tier-grid .prediction-tier-sure .number-ball,
body .prediction-tier-grid .prediction-tier-sure .number-ball:nth-child(n) {
    background: linear-gradient(145deg,#20bd5a,#0b7d3c) !important;
    box-shadow: inset 0 2px 3px rgba(255,255,255,.20), 0 9px 20px rgba(13,128,65,.22), 0 0 0 1px rgba(13,128,65,.13) !important;
}
body .prediction-tier-grid .prediction-tier-sure .number-ball::after {
    content: 'SURE' !important;
    background: #dcfce7 !important;
    color: #08743a !important;
}

body .prediction-tier-grid .prediction-tier-direct .number-ball,
body .prediction-tier-grid .prediction-tier-direct .number-ball:nth-child(n) {
    background: linear-gradient(145deg,#e0a72c,#a96e05) !important;
    box-shadow: inset 0 2px 3px rgba(255,255,255,.22), 0 9px 20px rgba(168,110,5,.20), 0 0 0 1px rgba(168,110,5,.12) !important;
}
body .prediction-tier-grid .prediction-tier-direct .number-ball::after {
    content: 'DIRECT' !important;
    background: #fff1c7 !important;
    color: #885904 !important;
}

/* Force countdown contrast above legacy declarations. */
body .next-prediction-card .prediction-countdown-box {
    min-height: 112px !important;
    display: grid !important;
    place-content: center !important;
    margin: 17px 0 18px !important;
    padding: 14px 16px !important;
    border: 1px solid rgba(76,139,190,.32) !important;
    border-radius: 16px !important;
    background: linear-gradient(135deg,#07192b 0%,#0d3150 100%) !important;
    box-shadow: 0 14px 28px rgba(7,25,45,.16) !important;
    text-align: center !important;
}
body .next-prediction-card .prediction-countdown-box p {
    margin: 0 0 6px !important;
    color: #b9d2e7 !important;
    opacity: 1 !important;
    text-shadow: none !important;
}
body .next-prediction-card #countdown-timer,
body .next-prediction-card #ghana-countdown-timer {
    color: #ffffff !important;
    opacity: 1 !important;
    text-shadow: 0 6px 18px rgba(0,0,0,.28) !important;
}

/* Keep the cards comfortably wide; stack before tablet/small-desktop squeeze. */
@media (max-width: 1120px) {
    body .prediction-cards-grid {
        grid-template-columns: 1fr !important;
        width: min(820px,100%) !important;
        margin-left: auto !important;
        margin-right: auto !important;
        gap: 20px !important;
    }

    body .prediction-cards-grid .next-prediction-card {
        width: 100% !important;
        max-width: none !important;
    }

    body .modern-prediction-card .prediction-analysis-summary {
        grid-template-columns: repeat(3,minmax(0,1fr)) !important;
    }

    body .ghana-analysis-summary {
        display: grid !important;
        grid-template-columns: repeat(2,minmax(0,1fr)) !important;
        gap: 10px !important;
    }
}

/* Tighter forecast stage: remove excess vertical air. */
body .prediction-number-area {
    min-height: 0 !important;
    padding-top: 18px !important;
    padding-bottom: 18px !important;
}
body .prediction-number-area .prediction-share-btn {
    margin-top: 3px !important;
}
body .prediction-analysis-summary {
    margin-bottom: 0 !important;
}

@media (max-width: 700px) {
    body .prediction-balls.prediction-tier-grid {
        grid-template-columns: 1fr !important;
        gap: 10px !important;
        margin: 17px auto 14px !important;
    }

    body .prediction-tier-grid .prediction-tier {
        min-height: 116px !important;
        padding: 13px 10px 18px !important;
    }

    body .prediction-tier-balls {
        gap: 12px !important;
    }

    body .modern-prediction-card .prediction-analysis-summary,
    body .ghana-analysis-summary {
        grid-template-columns: 1fr !important;
    }
}
'''

css = css_path.read_text(encoding='utf-8')
if marker not in css:
    css_path.write_text(css.rstrip() + patch + '\n', encoding='utf-8')
    print('appended prediction correction CSS')
else:
    print('prediction correction CSS already present')

html = html_path.read_text(encoding='utf-8')
old = 'predictions-premium-v4.css?v=1'
new = 'predictions-premium-v4.css?v=2'
if old in html:
    html = html.replace(old, new)
    html_path.write_text(html, encoding='utf-8')
    print('bumped predictions premium asset to v2')
elif new in html:
    print('predictions premium asset already at v2')
else:
    raise SystemExit('predictions premium stylesheet reference not found')
